def lis_length(nums: list[int]) -> int:
    """
    Given a list of integers, find the length of the longest strictly increasing subsequence of nums.
    For example:
    lis_length([10,9,2,5,3,7,101,18]) == 4
    lis_length([0,1,0,3,2,3]) == 4
    lis_length([7,7,7,7,7,7,7]) == 1
    """
    tails = []
    for num in nums:
        if not tails or num > tails[-1]:
            tails.append(num)
        else:
            l, r = 0, len(tails) - 1
            while l <= r:
                mid = (l + r) // 2
                if tails[mid] < num:
                    l = mid + 1
                else:
                    r = mid - 1
            tails[l] = num
    return len(tails)
