def paths_with_obstacles(grid: list[list[int]]) -> int:
    """
    Given a grid of integers, determine the number of distinct paths from the top-left cell to the bottom-right cell.
    Cells containing 1 are blocked. Return the number of distinct paths.
    """
    rows, cols = len(grid), len(grid[0])
    if grid[0][0] == 1 or grid[rows - 1][cols - 1] == 1:
        return 0

    dp = [[0] * cols for _ in range(rows)]
    dp[0][0] = 1

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1:
                continue
            if i > 0:
                dp[i][j] += dp[i - 1][j]
            if j > 0:
                dp[i][j] += dp[i][j - 1]

    return dp[rows - 1][cols - 1]

