def longest_palindrome(s: str) -> str:
    """
    Given a string s, return the longest palindromic contiguous substring of s.
    If several have the maximum length, return the one that starts earliest.
    Return '' for ''.
    """
    if not s:
        return ""

    longest_pal = ""
    for i in range(len(s)):
        for j in range(i, len(s)):
            substring = s[i:j+1]
            if substring == substring[::-1]:
                if len(substring) > len(longest_pal):
                    longest_pal = substring
                elif len(substring) == len(longest_pal) and i < s.find(substring) + 1:
                    longest_pal = substring

    return longest_pal
