    """
    Given a string of digits, return the number of ways to decode it.
    Codes with a leading zero, such as '06', are invalid.
    Return 0 if no decoding exists.
    """
    def solve(index, prev_digit):
        if index == len(s):
            return 1
        if s[index] == '0':
            return 0
        ans = 0
        for digit in range(10):
            if digit != prev_digit:
                ans += solve(index + 1, digit)
        return ans

